using System.Collections;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEngine.Events;

public static class TransformExtensions
{
	public static Transform GetLastChild(this Transform t)
	{
		return t.GetChild(t.childCount - 1);
	}

	public static Transform GetFirstChild(this Transform t)
	{
		return t.GetChild(0);
	}

	public static List<Transform> GetChildren(this Transform transform)
	{
		List<Transform> list = new List<Transform>();
		int childCount = transform.childCount;
		for (int i = 0; i < childCount; i++)
		{
			list.Add(transform.GetChild(i));
		}
		return list;
	}

	public static void ToggleChildren(this Transform transform, bool toggle)
	{
		int childCount = transform.childCount;
		for (int i = 0; i < childCount; i++)
		{
			transform.GetChild(i).gameObject.SetActive(toggle);
		}
	}

	public static void DestroyChildren<T>(this Transform root) where T : MonoBehaviour
	{
		T[] componentsInChildren = root.GetComponentsInChildren<T>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			if (!(componentsInChildren[i] == null) && !(componentsInChildren[i].transform == root))
			{
				if (Application.isPlaying)
				{
					Object.Destroy(componentsInChildren[i].gameObject);
				}
				else
				{
					Object.DestroyImmediate(componentsInChildren[i].gameObject);
				}
			}
		}
	}

	public static void DestroyChildren(this Transform root)
	{
		if (Application.isPlaying)
		{
			int childCount = root.childCount;
			for (int i = 0; i < childCount; i++)
			{
				Object.Destroy(root.GetChild(i).gameObject);
			}
		}
		else
		{
			root.DestroyChildrenDuringEditTime();
		}
	}

	public static void DestroyChildren(this Transform root, int startIndex)
	{
		if (Application.isPlaying)
		{
			int childCount = root.childCount;
			for (int i = startIndex; i < childCount; i++)
			{
				Object.Destroy(root.GetChild(i).gameObject);
			}
		}
		else
		{
			root.DestroyChildrenDuringEditTime();
		}
	}

	public static void DestroyChildrenDuringEditTime(this Transform root)
	{
		int childCount = root.childCount;
		List<Transform> list = new List<Transform>();
		for (int i = 0; i < childCount; i++)
		{
			list.Add(root.GetChild(i));
		}
		foreach (Transform item in list)
		{
			Object.DestroyImmediate(item.gameObject);
		}
	}

	public static void AddComponentToChildren<T>(this Transform transform) where T : Component
	{
		int childCount = transform.childCount;
		for (int i = 0; i < childCount; i++)
		{
			transform.GetChild(i).gameObject.AddComponent<T>();
		}
	}

	public static void EnableRendererInChildren<T>(this Transform transform, bool enabled) where T : Renderer
	{
		T[] componentsInChildren = transform.GetComponentsInChildren<T>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].enabled = enabled;
		}
	}

	public static void EnableComponentsInChildren<T>(this Transform transform, bool enabled) where T : Behaviour
	{
		T[] componentsInChildren = transform.GetComponentsInChildren<T>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].enabled = enabled;
		}
	}

	public static void EnableColliderInChildren<T>(this Transform transform, bool enabled) where T : Collider
	{
		T[] componentsInChildren = transform.GetComponentsInChildren<T>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].enabled = enabled;
		}
	}

	public static void SetLayerAndChildLayers(this Transform t, int layer)
	{
		t.gameObject.layer = layer;
		for (int i = 0; i < t.childCount; i++)
		{
			Transform child = t.GetChild(i);
			child.gameObject.layer = layer;
			child.SetChildLayers(layer);
		}
	}

	public static void SetChildLayers(this Transform t, int layer)
	{
		for (int i = 0; i < t.childCount; i++)
		{
			Transform child = t.GetChild(i);
			child.gameObject.layer = layer;
			child.SetChildLayers(layer);
		}
	}

	public static Vector3 GetCenterWeighted(this List<Transform> transforms)
	{
		Vector3 zero = Vector3.zero;
		int num = 0;
		if (transforms == null || transforms.Count == 0)
		{
			return zero;
		}
		for (int i = 0; i < transforms.Count; i++)
		{
			if (transforms[i] != null)
			{
				zero += transforms[i].position;
				num++;
			}
		}
		return zero / num;
	}

	public static Vector3 GetCenter(this List<Transform> transforms)
	{
		if (transforms == null || transforms.Count == 0 || transforms[0] == null)
		{
			return Vector3.zero;
		}
		Vector3 position = transforms[0].position;
		Vector3 position2 = transforms[0].position;
		for (int i = 1; i < transforms.Count; i++)
		{
			if (transforms[i] != null)
			{
				Vector3 position3 = transforms[i].position;
				if (position3.x < position.x)
				{
					position.x = position3.x;
				}
				if (position3.x > position2.x)
				{
					position2.x = position3.x;
				}
				if (position3.y < position.y)
				{
					position.y = position3.y;
				}
				if (position3.y > position2.y)
				{
					position2.y = position3.y;
				}
				if (position3.z < position.z)
				{
					position.z = position3.z;
				}
				if (position3.z > position2.z)
				{
					position2.z = position3.z;
				}
			}
		}
		return Vector3.Lerp(position, position2, 0.5f);
	}

	public static T InstantiateChild<T>(this Transform transform, T prefab, Vector3? position = null, Quaternion? rotation = null, Vector3? scale = null) where T : Component
	{
		Vector3 position2 = position ?? transform.position;
		Quaternion rotation2 = rotation ?? Quaternion.identity;
		T val = Object.Instantiate(prefab, position2, rotation2);
		if (val != null)
		{
			val.name = prefab.name;
			if (scale.HasValue)
			{
				val.transform.localScale = scale.Value;
			}
			val.transform.SetParent(transform);
		}
		return val;
	}

	public static GameObject InstantiateChildGameObject(this Transform transform, GameObject prefab, Vector3? position = null, Quaternion? rotation = null, Vector3? scale = null)
	{
		Vector3 position2 = position ?? transform.position;
		Quaternion rotation2 = rotation ?? Quaternion.identity;
		GameObject gameObject = Object.Instantiate(prefab, position2, rotation2);
		if (gameObject != null)
		{
			gameObject.name = prefab.name;
			if (scale.HasValue)
			{
				gameObject.transform.localScale = scale.Value;
			}
			gameObject.transform.parent = transform;
		}
		return gameObject;
	}

	public static T[] GetInterfaces<T>(this Transform transform)
	{
		return (from component in transform.GetComponents<MonoBehaviour>()
			where component is T
			select (T)(object)component).ToArray();
	}

	public static T GetInterface<T>(this Transform transform)
	{
		return transform.GetInterfaces<T>().FirstOrDefault();
	}

	public static T[] GetInterfacesInChildren<T>(this Transform transform)
	{
		return (from component in transform.GetComponentsInChildren<MonoBehaviour>()
			where component is T
			select (T)(object)component).ToArray();
	}

	public static T GetInterfaceInChildren<T>(this Transform transform)
	{
		return transform.GetInterfacesInChildren<T>().FirstOrDefault();
	}

	public static T[] GetInterfacesInParentAndChildren<T>(this Transform transform)
	{
		if (transform.parent != null)
		{
			return transform.parent.GetInterfacesInChildren<T>();
		}
		return transform.GetInterfacesInChildren<T>();
	}

	public static T GetInterfaceInParentAndChildren<T>(this Transform transform)
	{
		return transform.GetInterfacesInParentAndChildren<T>().FirstOrDefault();
	}

	public static T[] GetInterfacesInRootAndChildren<T>(this Transform transform)
	{
		return transform.root.GetInterfacesInChildren<T>();
	}

	public static T GetInterfaceInRootAndChildren<T>(this Transform transform)
	{
		return transform.GetInterfacesInRootAndChildren<T>().FirstOrDefault();
	}

	public static void WaitForHeight(this Transform rb, MonoBehaviour starter, float target, UnityAction action)
	{
		starter.StartCoroutine(WaitForHeightEffect(rb, target, action));
	}

	private static IEnumerator WaitForHeightEffect(Transform t, float target, UnityAction action)
	{
		int way = ((t.position.y < target) ? 1 : (-1));
		yield return new WaitWhile(() => t.position.y * (float)way < target * (float)way);
		action();
	}

	public static int CountGrandChildren(this Transform parent)
	{
		int num = 0;
		for (int i = 0; i < parent.childCount; i++)
		{
			num += parent.GetChild(i).childCount;
		}
		return num;
	}

